def get_player_by_id(account_id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0023000" if __import__("os").path.isdir("./environment_mix/0023000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_player_by_id"

    # --- quota/rate logging helpers (best-effort; no separate auth context in schema) ---
    def _log(status, message=None, **meta):
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": datetime.datetime.utcnow().isoformat() + "Z",
        }
        if meta:
            row["meta"] = meta
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits():
        # If no request log collection exists, treat as unlimited but still record to it.
        # If it exists, enforce a simple global rate limit: 120 req/min, and daily quota 10k.
        logs = _load("request_logs.json")
        if not isinstance(logs, list) or len(logs) == 0:
            return None
        now = datetime.datetime.utcnow()
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        in_last_min = 0
        in_last_day = 0
        for r in logs:
            ts = _parse_ts(r.get("ts"))
            if not ts:
                continue
            if ts >= minute_ago:
                in_last_min += 1
            if ts >= day_ago:
                in_last_day += 1
        if in_last_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if in_last_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    try:
        if not isinstance(account_id, int):
            e = _err("VALIDATION_ERROR", "account_id must be an integer")
            try:
                _log("error", e["error"]["message"], code=e["error"]["code"])
            finally:
                return e
        if account_id <= 0:
            e = _err("VALIDATION_ERROR", "account_id must be a positive integer")
            try:
                _log("error", e["error"]["message"], code=e["error"]["code"])
            finally:
                return e

        limerr = _enforce_limits()
        if limerr:
            try:
                _log("error", limerr["error"]["message"], code=limerr["error"]["code"])
            finally:
                return limerr

        players = _load("players.json")
        if not isinstance(players, list):
            players = []

        player = None
        for p in players:
            if isinstance(p, dict) and p.get("steam32_account_id") == account_id:
                player = p
                break

        now = datetime.datetime.utcnow().isoformat() + "Z"

        if player is None:
            # Business rule: may create a minimal stale row.
            new_row = {
                "id": "pl_" + uuid.uuid4().hex,
                "steam32_account_id": account_id,
                "persona_name": None,
                "avatar_url": None,
                "profile_url": None,
                "country_code": None,
                "rank_tier": None,
                "leaderboard_rank": None,
                "is_pro": False,
                "pro_team_id": None,
                "pro_name": None,
                "last_match_id_seen": None,
                "profile_status": "stale",
                "last_refreshed_at": None,
                "created_at": now,
                "updated_at": now,
            }
            # enforce unique(steam32_account_id) (safe due to our scan)
            players.append(new_row)
            _save("players.json", players)
            player = new_row

        # Exclude deleted from being returned (service-style); if deleted, treat as NOT_FOUND.
        if player.get("profile_status") == "deleted":
            e = _err("NOT_FOUND", "Player not found")
            try:
                _log("error", e["error"]["message"], code=e["error"]["code"], account_id=account_id)
            finally:
                return e

        # "normalized player snapshot": return stored row plus any extension blobs if present.
        # Do not fabricate fields; return as-is.
        resp = {"player": player}
        try:
            _log("ok", None, account_id=account_id)
        finally:
            return resp
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected server error", detail=str(ex))
        try:
            _log("error", e["error"]["message"], code=e["error"]["code"])
        finally:
            return e

def get_player_recent_matches(account_id, limit=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0023000" if __import__("os").path.isdir("./environment_mix/0023000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_player_recent_matches"

    def _log(status, message=None, **meta):
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": datetime.datetime.utcnow().isoformat() + "Z",
        }
        if meta:
            row["meta"] = meta
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list) or len(logs) == 0:
            return None
        now = datetime.datetime.utcnow()
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        in_last_min = 0
        in_last_day = 0
        for r in logs:
            ts = _parse_ts(r.get("ts"))
            if not ts:
                continue
            if ts >= minute_ago:
                in_last_min += 1
            if ts >= day_ago:
                in_last_day += 1
        if in_last_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if in_last_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    try:
        if not isinstance(account_id, int):
            e = _err("VALIDATION_ERROR", "account_id must be an integer")
            try:
                _log("error", e["error"]["message"], code=e["error"]["code"])
            finally:
                return e
        if account_id <= 0:
            e = _err("VALIDATION_ERROR", "account_id must be a positive integer")
            try:
                _log("error", e["error"]["message"], code=e["error"]["code"])
            finally:
                return e

        if limit is None:
            limit = 5
        if not isinstance(limit, int):
            e = _err("VALIDATION_ERROR", "limit must be an integer")
            try:
                _log("error", e["error"]["message"], code=e["error"]["code"], account_id=account_id)
            finally:
                return e
        if limit < 1 or limit > 100:
            e = _err("VALIDATION_ERROR", "limit must be between 1 and 100")
            try:
                _log("error", e["error"]["message"], code=e["error"]["code"], account_id=account_id)
            finally:
                return e

        limerr = _enforce_limits()
        if limerr:
            try:
                _log("error", limerr["error"]["message"], code=limerr["error"]["code"], account_id=account_id)
            finally:
                return limerr

        players = _load("players.json")
        if not isinstance(players, list):
            players = []
        exists_player = any(isinstance(p, dict) and p.get("steam32_account_id") == account_id and p.get("profile_status") != "deleted" for p in players)
        if not exists_player:
            e = _err("NOT_FOUND", "Player not found")
            try:
                _log("error", e["error"]["message"], code=e["error"]["code"], account_id=account_id)
            finally:
                return e

        mp = _load("match_players.json")
        if not isinstance(mp, list):
            mp = []
        match_ids = set()
        for r in mp:
            if not isinstance(r, dict):
                continue
            if r.get("row_status") == "deleted":
                continue
            if r.get("player_account_id") == account_id:
                mid = r.get("match_id")
                if isinstance(mid, int):
                    match_ids.add(mid)

        if not match_ids:
            # Well-formed read: empty list, not error.
            out = {"matches": [], "meta": {"total": 0, "limit": limit, "has_more": False}}
            try:
                _log("ok", None, account_id=account_id)
            finally:
                return out

        matches = _load("matches.json")
        if not isinstance(matches, list):
            matches = []

        by_mid = {}
        for m in matches:
            if isinstance(m, dict) and isinstance(m.get("match_id"), int):
                by_mid[m["match_id"]] = m

        rows = []
        for mid in match_ids:
            m = by_mid.get(mid)
            if m is not None and m.get("match_status") != "deleted":
                rows.append(m)

        def _parse_dt(v):
            if not isinstance(v, str):
                return None
            try:
                s = v[:-1] if v.endswith("Z") else v
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        def _sort_key(m):
            st = _parse_dt(m.get("start_time"))
            # order: start_time desc, nulls last; tie-break match_id desc
            return (st is not None, st or datetime.datetime.min, m.get("match_id") or 0)

        rows.sort(key=_sort_key, reverse=True)
        total = len(rows)
        rows = rows[:limit]
        out = {"matches": rows, "meta": {"total": total, "limit": limit, "has_more": total > limit}}
        try:
            _log("ok", None, account_id=account_id, limit=limit)
        finally:
            return out
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected server error", detail=str(ex))
        try:
            _log("error", e["error"]["message"], code=e["error"]["code"])
        finally:
            return e

