def get_player_win_loss(account_id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0023000" if __import__("os").path.isdir("./environment_mix/0023000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_player_win_loss"
    t0 = time.time()
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if not v:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.utcfromtimestamp(v)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1]
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _log(status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "timestamp": now_iso,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        one_min = now - datetime.timedelta(seconds=60)
        one_day = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in logs[-20000:]:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("timestamp") or r.get("ts"))
            if not ts:
                continue
            if ts >= one_day:
                c_day += 1
                if ts >= one_min:
                    c_min += 1
        if c_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if c_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    # Validate
    if not isinstance(account_id, int):
        e = _err("VALIDATION_ERROR", "account_id must be an integer", account_id=account_id)
        _log("error", {"error": e["error"]})
        return e
    if account_id <= 0:
        e = _err("VALIDATION_ERROR", "account_id must be > 0", account_id=account_id)
        _log("error", {"error": e["error"]})
        return e

    rl = _rate_limit_check()
    if rl:
        _log("error", {"error": rl["error"]})
        return rl

    players = _load("players.json")
    if not isinstance(players, list):
        players = []
    player_exists = any(isinstance(p, dict) and p.get("steam32_account_id") == account_id and p.get("profile_status") != "deleted" for p in players)
    if not player_exists:
        # Per tool description: NOT_FOUND if player snapshot does not exist
        e = _err("NOT_FOUND", "Player snapshot not found", account_id=account_id)
        _log("error", {"error": e["error"]})
        return e

    mps = _load("match_players.json")
    if not isinstance(mps, list):
        mps = []
    wins = 0
    losses = 0
    for r in mps:
        if not isinstance(r, dict):
            continue
        if r.get("row_status") == "deleted":
            continue
        if r.get("player_account_id") != account_id:
            continue
        won = r.get("won")
        if won is True:
            wins += 1
        elif won is False:
            losses += 1

    # OpenDota-style endpoints typically return zeros when no data; do not error on empty
    resp = {"account_id": account_id, "win": wins, "lose": losses}
    _log("ok", {"account_id": account_id, "win": wins, "lose": losses})
    return resp

def search_player(query, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0023000" if __import__("os").path.isdir("./environment_mix/0023000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "search_player"

    def _log(status, detail=None):
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow().isoformat() + "Z"
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        # Rate limit: 60/min due to search cost; Daily quota: 2000/day
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        day_start = now - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in logs:
            if r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= day_start:
                per_day += 1
            if dt >= window_start:
                per_min += 1
        if per_min >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if per_day >= 2000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    rl = _enforce_limits()
    if rl:
        _log(rl["error"]["code"], rl["error"]["message"])
        return rl

    if not isinstance(query, str):
        e = _err("VALIDATION_ERROR", "query must be a string")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    q = query.strip()
    if not q:
        e = _err("VALIDATION_ERROR", "query must be non-empty")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e

    players = _load("players.json")
    ql = q.casefold()
    max_results = 50  # safe server-side cap

    out = []
    for p in players:
        if p.get("profile_status") == "deleted":
            continue
        persona = p.get("persona_name")
        proname = p.get("pro_name")
        hay1 = persona.casefold() if isinstance(persona, str) else ""
        hay2 = proname.casefold() if isinstance(proname, str) else ""
        if ql in hay1 or ql in hay2:
            out.append({
                "account_id": p.get("steam32_account_id"),
                "persona_name": p.get("persona_name"),
                "avatar_url": p.get("avatar_url"),
                "profile_url": p.get("profile_url"),
                "country_code": p.get("country_code"),
                "is_pro": p.get("is_pro"),
                "pro_name": p.get("pro_name"),
                "pro_team_id": p.get("pro_team_id"),
                "rank_tier": p.get("rank_tier"),
                "leaderboard_rank": p.get("leaderboard_rank"),
                "profile_status": p.get("profile_status"),
            })
            if len(out) >= max_results:
                break

    resp = {"data": out, "meta": {"query": q, "count": len(out), "cap": max_results}}
    _log("OK")
    return resp

def get_pro_players(limit=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0023000" if __import__("os").path.isdir("./environment_mix/0023000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_pro_players"

    def _log(status, detail=None):
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow().isoformat() + "Z"
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        # Rate limit: 120/min per endpoint
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        per_min = 0
        for r in logs:
            if r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                per_min += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    rl = _enforce_limits()
    if rl:
        _log(rl["error"]["code"], rl["error"]["message"])
        return rl

    if limit is None:
        limit = 10
    if not isinstance(limit, int):
        e = _err("VALIDATION_ERROR", "limit must be an integer")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e
    if limit < 1 or limit > 100:
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 100")
        _log("VALIDATION_ERROR", e["error"]["message"])
        return e

    players = _load("players.json")
    pros = [p for p in players if p.get("is_pro") is True and p.get("profile_status") != "deleted"]

    def _sort_key(p):
        lr = p.get("leaderboard_rank")
        # leaderboard_rank asc, nulls last
        return (0, lr) if isinstance(lr, int) else (1, 10**18)

    pros.sort(key=_sort_key)
    pros = pros[:limit]

    out = []
    for p in pros:
        out.append({
            "account_id": p.get("steam32_account_id"),
            "persona_name": p.get("persona_name"),
            "avatar_url": p.get("avatar_url"),
            "profile_url": p.get("profile_url"),
            "country_code": p.get("country_code"),
            "rank_tier": p.get("rank_tier"),
            "leaderboard_rank": p.get("leaderboard_rank"),
            "pro_team_id": p.get("pro_team_id"),
            "pro_name": p.get("pro_name"),
            "last_match_id_seen": p.get("last_match_id_seen"),
            "profile_status": p.get("profile_status"),
            "last_refreshed_at": p.get("last_refreshed_at"),
            "updated_at": p.get("updated_at"),
        })

    resp = {"data": out, "meta": {"limit": limit, "total": len([p for p in players if p.get("is_pro") is True and p.get("profile_status") != "deleted"])}}
    _log("OK")
    return resp

def get_pro_matches(limit=None, **_extra):
