    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_pro_matches"
    status = "success"

    # Usage logging & basic rate limiting (best-effort; schema not provided)
    usage_file = "request_logs.json"
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_and_maybe_limit(planned_status):
        logs = _load(usage_file)
        if not isinstance(logs, list):
            logs = []
        # Rate limit: 120 requests/min per service (no explicit auth context in schema)
        window_s = 60
        limit_per_window = 120
        cutoff = time.time() - window_s
        recent = 0
        for r in logs:
            try:
                ts = r.get("ts_epoch")
                if isinstance(ts, (int, float)) and ts >= cutoff:
                    recent += 1
            except Exception:
                pass
        if recent >= limit_per_window:
            # log refused request
            logs.append({
                "id": f"rl_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "ts": now_iso,
                "ts_epoch": time.time(),
                "status": "RATE_LIMIT",
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save(usage_file, logs)
            return _err("RATE_LIMIT", "Rate limit exceeded")
        # no limit hit yet; caller will log at end
        return None

    # Validate inputs
    if limit is None:
        limit = 5
    if not isinstance(limit, int):
        status = "VALIDATION_ERROR"
        rl = _log_and_maybe_limit(status)
        if rl:  # even validation errors count against rate limit
            return rl
        logs = _load(usage_file)
        if not isinstance(logs, list): logs = []
        logs.append({"id": f"rl_{int(time.time()*1000)}", "endpoint": endpoint, "ts": now_iso, "ts_epoch": time.time(), "status": status, "latency_ms": int((time.time()-t0)*1000)})
        _save(usage_file, logs)
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 100:
        status = "VALIDATION_ERROR"
        rl = _log_and_maybe_limit(status)
        if rl:
            return rl
        logs = _load(usage_file)
        if not isinstance(logs, list): logs = []
        logs.append({"id": f"rl_{int(time.time()*1000)}", "endpoint": endpoint, "ts": now_iso, "ts_epoch": time.time(), "status": status, "latency_ms": int((time.time()-t0)*1000)})
        _save(usage_file, logs)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")

    rl = _log_and_maybe_limit("success")
    if rl:
        return rl

    matches = _load("matches.json")
    if not isinstance(matches, list):
        matches = []

    pro = [m for m in matches if isinstance(m, dict) and m.get("is_pro") is True and m.get("match_status") != "deleted"]
    def _key(m):
        st = m.get("start_time")
        # if start_time is ISO-like string, sort lexicographically is OK for same format; else fallback
        if isinstance(st, str) and st:
            return (0, st)
        # fallback to match_id desc
        mid = m.get("match_id")
        return (1, mid if isinstance(mid, int) else -1)

    pro.sort(key=_key, reverse=True)
    out = pro[:limit]

    logs = _load(usage_file)
    if not isinstance(logs, list): logs = []
    logs.append({
        "id": f"rl_{int(time.time()*1000)}",
        "endpoint": endpoint,
        "ts": now_iso,
        "ts_epoch": time.time(),
        "status": status,
        "latency_ms": int((time.time() - t0) * 1000),
    })
    _save(usage_file, logs)

    return {
        "matches": out,
        "meta": {
            "limit": limit,
            "returned": len(out),
            "total_pro_matches": len(pro),
        }
    }

def get_player_peers(account_id, limit=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0023000" if __import__("os").path.isdir("./environment_mix/0023000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_player_peers"
    usage_file = "request_logs.json"
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status):
        logs = _load(usage_file)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rl_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "ts": now_iso,
            "ts_epoch": time.time(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(usage_file, logs)

    def _rate_limit():
        logs = _load(usage_file)
        if not isinstance(logs, list):
            logs = []
        window_s = 60
        limit_per_window = 120
        cutoff = time.time() - window_s
        recent = 0
        for r in logs:
            ts = r.get("ts_epoch") if isinstance(r, dict) else None
            if isinstance(ts, (int, float)) and ts >= cutoff:
                recent += 1
        if recent >= limit_per_window:
            logs.append({
                "id": f"rl_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "ts": now_iso,
                "ts_epoch": time.time(),
                "status": "RATE_LIMIT",
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save(usage_file, logs)
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    # Validate inputs
    if not isinstance(account_id, int):
        rl = _rate_limit()
        if rl:
            return rl
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id must be an integer")
    if account_id <= 0:
        rl = _rate_limit()
        if rl:
            return rl
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id must be > 0")

    if limit is None:
        limit = 5
    if not isinstance(limit, int):
        rl = _rate_limit()
        if rl:
            return rl
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 100:
        rl = _rate_limit()
        if rl:
            return rl
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")

    rl = _rate_limit()
    if rl:
        return rl

    players = _load("players.json")
    if not isinstance(players, list):
        players = []

    # Ensure player exists? Business rules specify creation only for get_player_by_id.
    # For peers computation, if no player row exists, treat as NOT_FOUND.
    subject = None
    for p in players:
        if isinstance(p, dict) and p.get("steam32_account_id") == account_id and p.get("profile_status") != "deleted":
            subject = p
            break
    if subject is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Player not found")

    match_players = _load("match_players.json")
    if not isinstance(match_players, list):
        match_players = []

    # Find matches the subject participated in
    subject_match_ids = set()
    for mp in match_players:
        if not isinstance(mp, dict):
            continue
        if mp.get("row_status") == "deleted":
            continue
        if mp.get("player_account_id") == account_id:
            mid = mp.get("match_id")
            if isinstance(mid, int):
                subject_match_ids.add(mid)

    if not subject_match_ids:
        _log("success")
        return {"account_id": account_id, "peers": [], "meta": {"limit": limit, "returned": 0, "matches_considered": 0}}

    # Aggregate peers: games and wins together (from the subject's won)
    subject_won_by_match = {}
    for mp in match_players:
        if not isinstance(mp, dict):
            continue
        if mp.get("row_status") == "deleted":
            continue
        if mp.get("player_account_id") == account_id:
            mid = mp.get("match_id")
            if isinstance(mid, int):
                w = mp.get("won")
                if isinstance(w, bool) or w is None:
                    subject_won_by_match[mid] = w

    agg = {}  # peer_account_id -> {games, wins}
    for mp in match_players:
        if not isinstance(mp, dict):
            continue
        if mp.get("row_status") == "deleted":
            continue
        mid = mp.get("match_id")
        if mid not in subject_match_ids:
            continue
        peer_id = mp.get("player_account_id")
        if not isinstance(peer_id, int) or peer_id == account_id:
            continue
        a = agg.get(peer_id)
        if a is None:
            a = {"account_id": peer_id, "games": 0, "wins": 0}
            agg[peer_id] = a
        a["games"] += 1
        w = subject_won_by_match.get(mid)
        if w is True:
            a["wins"] += 1

    peers = list(agg.values())
    # order: games desc, wins desc, account_id asc
    peers.sort(key=lambda x: (-x["games"], -x["wins"], x["account_id"]))

    # Join player identity fields where available
    idx = {}
    for p in players:
        if isinstance(p, dict):
            sid = p.get("steam32_account_id")
            if isinstance(sid, int):
                idx[sid] = p

    out = []
    for row in peers[:limit]:
        p = idx.get(row["account_id"])
        out.append({
            "account_id": row["account_id"],
            "games": row["games"],
            "wins": row["wins"],
            "with_win_rate": (row["wins"] / row["games"]) if row["games"] else None,
            "persona_name": p.get("persona_name") if isinstance(p, dict) else None,
            "pro_name": p.get("pro_name") if isinstance(p, dict) else None,
            "avatar_url": p.get("avatar_url") if isinstance(p, dict) else None,
            "is_pro": p.get("is_pro") if isinstance(p, dict) else False,
        })

    _log("success")
    return {
        "account_id": account_id,
        "peers": out,
        "meta": {
            "limit": limit,
            "returned": len(out),
            "matches_considered": len(subject_match_ids),
            "distinct_peers": len(peers),
        }
    }

def get_heroes(primary_attr=None, attack_type=None, stats_status=None, search=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0023000" if __import__("os").path.isdir("./environment_mix/0023000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_heroes"
    usage_file = "request_logs.json"
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    allowed_primary = {"str", "agi", "int", "all"}
    allowed_attack = {"Melee", "Ranged"}
    allowed_stats = {"fresh", "stale", "disabled"}
    allowed_sort = {"external_hero_id", "localized_name", "name", "primary_attr", "attack_type", "last_stats_refreshed_at", "created_at", "updated_at"}
    allowed_order = {"asc", "desc"}

    def _log(status):
        logs = _load(usage_file)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rl_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "ts": now_iso,
            "ts_epoch": time.time(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(usage_file, logs)

    def _rate_limit():
        logs = _load(usage_file)
        if not isinstance(logs, list):
            logs = []
        window_s = 60
        limit_per_window = 120
        cutoff = time.time() - window_s
        recent = 0
        for r in logs:
            ts = r.get("ts_epoch") if isinstance(r, dict) else None
            if isinstance(ts, (int, float)) and ts >= cutoff:
                recent += 1
        if recent >= limit_per_window:
            logs.append({
                "id": f"rl_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "ts": now_iso,
                "ts_epoch": time.time(),
                "status": "RATE_LIMIT",
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save(usage_file, logs)
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    # Defaults
    if limit is None:
        limit = 100
    if sort is None:
        sort = "external_hero_id"
    if order is None:
        order = "asc"

    # Validate filters/enums
    if primary_attr is not None and primary_attr not in allowed_primary:
        rl = _rate_limit()
        if rl: return rl
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid primary_attr", allowed=list(sorted(allowed_primary)))
    if attack_type is not None and attack_type not in allowed_attack:
        rl = _rate_limit()
        if rl: return rl
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid attack_type", allowed=list(sorted(allowed_attack)))
    if stats_status is not None and stats_status not in allowed_stats:
        rl = _rate_limit()
        if rl: return rl
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid stats_status", allowed=list(sorted(allowed_stats)))
    if search is not None and not isinstance(search, str):
        rl = _rate_limit()
        if rl: return rl
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "search must be a string")
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        rl = _rate_limit()
        if rl: return rl
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")
    if sort not in allowed_sort:
        rl = _rate_limit()
        if rl: return rl
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort", allowed=list(sorted(allowed_sort)))
    if order not in allowed_order:
        rl = _rate_limit()
        if rl: return rl
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid order", allowed=list(sorted(allowed_order)))
    if cursor is not None and not isinstance(cursor, str):
        rl = _rate_limit()
        if rl: return rl
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string")

    rl = _rate_limit()
    if rl:
        return rl

    # Cursor format: base64url(json({"v":1,"offset":int,"sig":str}))
    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            cobj = json.loads(raw)
        except Exception:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor")
        if not isinstance(cobj, dict) or cobj.get("v") != 1 or not isinstance(cobj.get("offset"), int):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor")
        if cobj["offset"] < 0:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor")
        offset = cobj["offset"]

    heroes = _load("heroes.json")
    if not isinstance(heroes, list):
        heroes = []
    # Filter rows with heroes.id exists
    rows = [h for h in heroes if isinstance(h, dict) and isinstance(h.get("id"), str) and h.get("id")]

    if primary_attr is not None:
        rows = [h for h in rows if h.get("primary_attr") == primary_attr]
    if attack_type is not None:
        rows = [h for h in rows if h.get("attack_type") == attack_type]
    if stats_status is not None:
        rows = [h for h in rows if h.get("stats_status") == stats_status]
    if search:
        q = search.casefold()
        def _m(h):
            a = h.get("name") or ""
            b = h.get("localized_name") or ""
            return (isinstance(a, str) and q in a.casefold()) or (isinstance(b, str) and q in b.casefold())
        rows = [h for h in rows if _m(h)]

    # Sorting
    def _sv(v):
        # for None handling: None last for asc, first for desc? API doesn't specify; use None last always.
        return (v is None, v)

    reverse = (order == "desc")
    try:
        rows.sort(key=lambda h: _sv(h.get(sort)), reverse=reverse)
    except TypeError:
        # Mixed incomparable types; coerce to string for stability
        rows.sort(key=lambda h: _sv(str(h.get(sort)) if h.get(sort) is not None else None), reverse=reverse)

    total = len(rows)
    if offset > total:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid/expired cursor")

    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        cobj = {"v": 1, "offset": next_offset}
        raw = json.dumps(cobj, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    _log("success")
    return {
        "heroes": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order,
            "offset": offset,
            "returned": len(page),
        }
    }

def get_player_totals(account_id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0023000" if __import__("os").path.isdir("./environment_mix/0023000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_player_totals"
    t0 = time.time()
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if not v:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.utcfromtimestamp(v)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1]
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _log(status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "timestamp": now_iso,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        one_min = now - datetime.timedelta(seconds=60)
        one_day = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in logs[-20000:]:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("timestamp") or r.get("ts"))
            if not ts:
                continue
            if ts >= one_day:
                c_day += 1
                if ts >= one_min:
                    c_min += 1
        if c_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if c_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    # Validate
    if not isinstance(account_id, int):
