        "hero_damage", "hero_healing", "tower_damage",
    ]
    totals = {k: 0 for k in fields}
    counts = {k: 0 for k in fields}  # for per-match averages if desired by clients
    matches_seen = set()

    for r in mps:
        if not isinstance(r, dict):
            continue
        if r.get("row_status") == "deleted":
            continue
        if r.get("player_account_id") != account_id:
            continue
        mid = r.get("match_id")
