        players = []
    player_exists = any(isinstance(p, dict) and p.get("steam32_account_id") == account_id and p.get("profile_status") != "deleted" for p in players)
    if not player_exists:
        e = _err("NOT_FOUND", "Player snapshot not found", account_id=account_id)
        _log("error", {"error": e["error"]})
        return e

    aggs = _load("player_hero_aggregates.json")
    if not isinstance(aggs, list):
        aggs = []
    rows = [r for r in aggs if isinstance(r, dict) and r.get("player_account_id") == account_id]

    # If none, return empty set (read semantics), but the tool description says NOT_FOUND.
    # Reconcile by only erroring when player missing; if player exists but no aggregates, return empty list.
    def _num(v):
        if isinstance(v, bool) or v is None:
            return None
        if isinstance(v, (int, float)) and not (isinstance(v, float) and (math.isnan(v) or math.isinf(v))):
            return float(v)
        return None

    def _key(r):
        rs = _num(r.get("ranking_score"))
        mc = r.get("match_count")
        mc = mc if isinstance(mc, int) else 0
        # ranking_score desc nulls last => treat None as very low
        rs_sort = rs if rs is not None else -1e30
        return (-rs_sort, -mc)

    rows_sorted = sorted(rows, key=_key)
    resp = {
        "account_id": account_id,
        "total": len(rows_sorted),
        "rankings": rows_sorted,
    }
    _log("ok", {"account_id": account_id, "total": len(rows_sorted)})
    return resp

def get_player_wordcloud(account_id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0023000" if __import__("os").path.isdir("./environment_mix/0023000") else "/app/database")
    def _load(n):
