            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_player_wordcloud"
    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_dt(v):
        if not v:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.utcfromtimestamp(v)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1]
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _log(status, meta=None, credential_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "timestamp": now_iso,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    # Global endpoint-level rate limit (no explicit credential parameter)
    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now2 = datetime.datetime.utcnow()
        one_min = now2 - datetime.timedelta(seconds=60)
        one_day = now2 - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in logs[-50000:]:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("timestamp") or r.get("ts"))
            if not ts:
                continue
            if ts >= one_day:
                c_day += 1
                if ts >= one_min:
                    c_min += 1
        if c_min >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if c_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    # Validate input
    if not isinstance(account_id, int):
        rl = _rate_limit_check()
        if rl:
            _log("error", {"error": rl["error"], "account_id": account_id})
            return rl
        e = _err("VALIDATION_ERROR", "account_id must be an integer", account_id=account_id)
        _log("error", {"error": e["error"], "account_id": account_id})
        return e
    if account_id <= 0:
        rl = _rate_limit_check()
        if rl:
            _log("error", {"error": rl["error"], "account_id": account_id})
            return rl
        e = _err("VALIDATION_ERROR", "account_id must be > 0", account_id=account_id)
        _log("error", {"error": e["error"], "account_id": account_id})
        return e

    rl = _rate_limit_check()
    if rl:
        _log("error", {"error": rl["error"], "account_id": account_id})
        return rl

    # Find player by steam32_account_id; if missing, create minimal stale snapshot
    players = _load("players.json")
    if not isinstance(players, list):
        players = []
    player = None
    for p in players:
        if isinstance(p, dict) and p.get("steam32_account_id") == account_id:
            player = p
            break

    if player is None:
        # Business rule allows creation of minimal row for unknown player id
        ts = now_iso
        new_id = "od_plr_" + uuid.uuid4().hex[:26]
        player = {
            "id": new_id,
            "steam32_account_id": account_id,
            "persona_name": None,
            "avatar_url": None,
            "profile_url": None,
            "country_code": None,
            "rank_tier": None,
            "leaderboard_rank": None,
            "is_pro": False,
            "pro_team_id": None,
            "pro_name": None,
            "last_match_id_seen": None,
            "profile_status": "stale",
            "last_refreshed_at": None,
            "created_at": ts,
            "updated_at": ts,
        }
        players.append(player)
        _save("players.json", players)

    # Enforce "FORBIDDEN when ... player's data is [disabled/deleted]"
    if player.get("profile_status") in ("disabled", "deleted"):
        e = _err("UNAUTHORIZED", "Player data is not accessible", account_id=account_id, profile_status=player.get("profile_status"))
        _log("error", {"error": e["error"], "account_id": account_id, "player_id": player.get("id")})
        return e

    # Serve cached wordcloud from an embedded blob in the player row.
    # Support a few likely storage shapes without requiring a new collection.
    wc = None
    if isinstance(player.get("wordcloud"), dict):
        wc = player.get("wordcloud")
    elif isinstance(player.get("word_cloud"), dict):
        wc = player.get("word_cloud")
    elif isinstance(player.get("additional_profile"), dict):
        ap = player.get("additional_profile")
        if isinstance(ap.get("wordcloud"), dict):
            wc = ap.get("wordcloud")
        elif isinstance(ap.get("word_cloud"), dict):
            wc = ap.get("word_cloud")
    elif isinstance(player.get("profile"), dict):
        prof = player.get("profile")
        if isinstance(prof.get("wordcloud"), dict):
            wc = prof.get("wordcloud")
        elif isinstance(prof.get("word_cloud"), dict):
            wc = prof.get("word_cloud")

    # If absent, compute a small wordcloud from available chat samples in match payloads (best-effort),
    # then persist it back into the player row (observably changes datastore).
    def _tokenize(text):
        if not isinstance(text, str):
            return []
        out = []
        buf = []
        for ch in text.lower():
            if ch.isalnum() or ch in ("'",):
                buf.append(ch)
            else:
                if buf:
                    out.append("".join(buf))
                    buf = []
        if buf:
            out.append("".join(buf))
        # filter very short tokens
        return [w for w in out if len(w) >= 3]

    if wc is None:
        matches = _load("matches.json")
        if not isinstance(matches, list):
            matches = []
        mps = _load("match_players.json")
        if not isinstance(mps, list):
            mps = []

        player_match_ids = set()
        for mp in mps:
            if not isinstance(mp, dict):
                continue
            if mp.get("row_status") == "deleted":
                continue
            if mp.get("player_account_id") == account_id:
                mid = mp.get("match_id")
                if isinstance(mid, int):
                    player_match_ids.add(mid)

        # Aggregate tokens from match raw_payload chat logs (various possible shapes)
        counts = {}
        max_matches_scan = 100  # cap compute
        scanned = 0
        for m in matches:
            if scanned >= max_matches_scan:
                break
            if not isinstance(m, dict):
                continue
            mid = m.get("match_id")
            if mid not in player_match_ids:
                continue
            scanned += 1
            payload = m.get("raw_payload")
            if not isinstance(payload, dict):
                continue
            # common upstream shapes: payload["chat"], payload["chatlog"], payload["all_chat"]
            chats = None
            for k in ("chat", "chatlog", "all_chat", "chat_log"):
                if isinstance(payload.get(k), list):
                    chats = payload.get(k)
                    break
            if not chats:
                continue
            for entry in chats:
                if not isinstance(entry, dict):
                    continue
                msg = entry.get("key") or entry.get("message") or entry.get("msg") or entry.get("text")
                # If chat entries contain account id, only include player's messages
                acc = entry.get("account_id") or entry.get("player_account_id") or entry.get("steam32_account_id")
                if acc is not None and acc != account_id:
                    continue
                for w in _tokenize(msg):
                    counts[w] = counts.get(w, 0) + 1

        if counts:
            top = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[:200]
            # OpenDota-like structure: my_word_counts / all_word_counts, but we at least return a dict.
            wc = {
                "my_word_counts": {k: v for k, v in top},
                "all_word_counts": {},
                "source": "derived_from_cached_match_payloads",
                "computed_at": now_iso,
            }
            # Persist into player row
            player["wordcloud"] = wc
            player["updated_at"] = now_iso
            _save("players.json", players)

    if not isinstance(wc, dict) or not wc:
        e = _err("NOT_FOUND", "No wordcloud data available", account_id=account_id)
        _log("error", {"error": e["error"], "account_id": account_id, "player_id": player.get("id")})
        return e

    resp = {
        "account_id": account_id,
        "player_id": player.get("id"),
        "wordcloud": wc,
        "cached": True,
    }
    _log("ok", {"account_id": account_id, "player_id": player.get("id")})
    return resp

