        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")

    matches = _load("matches.json")
    if not isinstance(matches, list):
        matches = []

    public = []
    for m in matches:
        if not isinstance(m, dict):
            continue
        if m.get("match_status") == "deleted":
            continue
        if m.get("is_pro") is True:
            continue
        public.append(m)

    def _match_sort_key(m):
        st = _parse_dt(m.get("start_time"))
        # order by start_time desc, fallback match_id desc
        mid = m.get("match_id")
        mid_val = mid if isinstance(mid, int) else -1
        if st is None:
            return (1, -mid_val)
        return (0, -int(st.timestamp()), -mid_val)

    public.sort(key=_match_sort_key)

    rows = []
    for m in public[:limit]:
        rows.append(
            {
                "match_id": m.get("match_id"),
                "start_time": m.get("start_time"),
                "duration": m.get("duration_seconds"),
                "radiant_win": m.get("radiant_win"),
                "radiant_score": m.get("radiant_score"),
                "dire_score": m.get("dire_score"),
                "game_mode": m.get("game_mode"),
                "lobby_type": m.get("lobby_type"),
                "region": m.get("region"),
            }
        )

    latency = int((time.time() - t0) * 1000)
    _log(endpoint, 200, latency, {"limit": limit, "returned": len(rows), "total_public": len(public)})

    return {
        "limit": limit,
        "total": len(public),
        "returned": len(rows),
        "rows": rows,
    }

def get_match_heroes(match_id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0023000" if __import__("os").path.isdir("./environment_mix/0023000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    endpoint = "get_match_heroes"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential": credential,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(credential=None):
        # Best-effort global rate/quotas based on request_logs.json.
        # If missing/unconfigured, allow.
        policies = _load("usage_policies.json")
        if not policies:
            return None
        pol = None
        # choose a policy applicable to this endpoint or default
        for p in policies:
            if p.get("endpoint") == endpoint and p.get("active", True):
                pol = p
                break
        if pol is None:
            for p in policies:
                if p.get("endpoint") in (None, "*", "default") and p.get("active", True):
                    pol = p
                    break
        if pol is None:
            return None

        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow()
        window_s = pol.get("rate_limit_window_seconds")
        max_in_window = pol.get("rate_limit_max_requests")
        if isinstance(window_s, int) and window_s > 0 and isinstance(max_in_window, int) and max_in_window >= 0:
            cutoff = now - datetime.timedelta(seconds=window_s)
            cnt = 0
            for r in logs:
                if credential is not None and r.get("credential") != credential:
                    continue
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    tsv = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if tsv >= cutoff:
                    cnt += 1
            if cnt >= max_in_window:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=max_in_window, window_seconds=window_s)

        day_max = pol.get("daily_quota_max_requests")
        if isinstance(day_max, int) and day_max >= 0:
            day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
            cnt = 0
            for r in logs:
                if credential is not None and r.get("credential") != credential:
                    continue
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    tsv = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if tsv >= day_start:
                    cnt += 1
            if cnt >= day_max:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota=day_max, period="day")

        return None

    # Validate input
    if not isinstance(match_id, int) or isinstance(match_id, bool) or match_id <= 0:
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "match_id must be a positive integer")

    # Quota/rate-limit (no explicit credential for this tool; use global bucket)
    lim_err = _enforce_limits(credential=None)
    if lim_err:
        _log("error", None, lim_err["error"]["code"])
        return lim_err

    # Authorization: ambient; only refuse if store defines an auth model and none can satisfy.
    # Since this tool has no credential param, we must not deny a well-formed request by default.
    # If an explicit auth store exists and indicates public access disabled, we enforce it.
    authz = _load("authz_policies.json")
    if authz:
        # find endpoint policy; if requires_auth == True, we cannot satisfy without a credential param
        for p in authz:
            if p.get("endpoint") == endpoint and p.get("requires_auth") is True:
                _log("error", None, "UNAUTHORIZED")
                return _err("UNAUTHORIZED", "No credential provided for an endpoint that requires authentication")

    matches = _load("matches.json")
    match_row = None
    for m in matches:
        if m.get("match_id") == match_id and m.get("match_status") != "deleted":
            match_row = m
            break
    if match_row is None:
        _log("error", None, "NOT_FOUND")
        return _err("NOT_FOUND", "Match not found")

    mp = _load("match_players.json")
    heroes = _load("heroes.json")
    hero_by_ext = {}
    for h in heroes:
        ext = h.get("external_hero_id")
        if isinstance(ext, int):
            hero_by_ext[ext] = h

    rows = []
    for r in mp:
        if r.get("match_id") != match_id:
            continue
        if r.get("row_status") == "deleted":
            continue
        hero_id = r.get("hero_id")
        h = hero_by_ext.get(hero_id)
        rows.append(
            {
                "match_id": match_id,
                "slot": r.get("slot"),
                "is_radiant": r.get("is_radiant"),
                "player_account_id": r.get("player_account_id"),
                "hero_id": hero_id,
                "hero_name": (h.get("name") if isinstance(h, dict) else None),
                "hero_localized_name": (h.get("localized_name") if isinstance(h, dict) else None),
            }
        )

    # Ensure at most 10 rows (fully populated match); deterministic ordering by slot asc.
    rows.sort(key=lambda x: (x["slot"] if isinstance(x.get("slot"), int) else 10**9))
    if len(rows) > 10:
        rows = rows[:10]

    _log("ok", None, None)
    return {
        "match_id": match_id,
        "count": len(rows),
        "heroes": rows,
    }

