        max_in_window = pol.get("rate_limit_max_requests")
        if isinstance(window_s, int) and window_s > 0 and isinstance(max_in_window, int) and max_in_window >= 0:
            cutoff = now - datetime.timedelta(seconds=window_s)
            cnt = 0
            for r in logs:
                if credential is not None and r.get("credential") != credential:
