        day_max = pol.get("daily_quota_max_requests")
        if isinstance(day_max, int) and day_max >= 0:
            day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
            cnt = 0
            for r in logs:
                if credential is not None and r.get("credential") != credential:
