        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id must be a positive integer")

    allowed = {"active", "stale", "disabled", "deleted"}
    if not isinstance(profile_status, str) or profile_status not in allowed:
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "profile_status must be one of: active, stale, disabled, deleted")

    if reason is not None and not isinstance(reason, str):
        _log("error", None, "VALIDATION_ERROR")
