            idx = i
            break

    if idx is None:
        _log("error", None, "NOT_FOUND")
        return _err("NOT_FOUND", "Player not found")

    lifecycle = {
        "active": {"stale", "disabled", "deleted"},
        "stale": {"active", "disabled", "deleted"},
        "disabled": {"active", "deleted"},
        "deleted": set(),
    }

    current = players[idx].get("profile_status")
    if current not in lifecycle:
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Player has an invalid stored profile_status", current=current)

    if profile_status == current:
        # Idempotent: no transition needed; but still must have effect? Real APIs often return current snapshot.
        # We'll treat as allowed no-op and update updated_at + audit trail to reflect the write.
        pass
    else:
        if profile_status not in lifecycle[current]:
            _log("error", None, "INVALID_TRANSITION")
            return _err(
                "INVALID_TRANSITION",
                "Requested profile_status transition is not allowed",
                from_status=current,
                to_status=profile_status,
            )
        players[idx]["profile_status"] = profile_status

    now = _now_iso()
    players[idx]["updated_at"] = now
    # Optionally record reason in an extension field (not part of schema but allowed as stored metadata)
    if reason is not None:
        audit = players[idx].get("status_audit")
        if not isinstance(audit, list):
            audit = []
        audit.append(
            {
                "at": now,
                "field": "profile_status",
                "from": current,
                "to": profile_status,
                "reason": reason,
            }
        )
        players[idx]["status_audit"] = audit

    _save("players.json", players)
    _log("ok", None, None)
    return {"player": players[idx]}

def get_auth_status(api_key, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0023000" if __import__("os").path.isdir("./environment_mix/0023000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_auth_status"
    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_dt(v):
        if not v:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.utcfromtimestamp(v)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1]
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _log(status, meta=None, credential_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "timestamp": now_iso,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    # Rate limit per credential if possible, otherwise global for endpoint.
    def _rate_limit_check(credential_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now2 = datetime.datetime.utcnow()
        one_min = now2 - datetime.timedelta(seconds=60)
        one_day = now2 - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in logs[-50000:]:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            if credential_id is not None and r.get("credential_id") != credential_id:
                continue
            ts = _parse_dt(r.get("timestamp") or r.get("ts"))
            if not ts:
                continue
            if ts >= one_day:
                c_day += 1
                if ts >= one_min:
                    c_min += 1
        # Conservative defaults
        if c_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if c_day >= 20000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    # Validate input
    if not isinstance(api_key, str) or not api_key.strip():
        e = _err("VALIDATION_ERROR", "api_key must be a non-empty string")
        _log("error", {"error": e["error"]})
        return e
    api_key = api_key.strip()

    # Authenticate against *client-visible* values or id across plausible credential stores.
    # Never compare against hashes/ciphertext.
    def _iter_rows(obj):
        if isinstance(obj, list):
            for r in obj:
                if isinstance(r, dict):
                    yield r
        elif isinstance(obj, dict):
            for k in ("rows", "data", "items", "credentials", "keys"):
                v = obj.get(k)
                if isinstance(v, list):
                    for r in v:
                        if isinstance(r, dict):
                            yield r

    def _matches_key(row, key):
        if not isinstance(row, dict):
            return False
        # Common field names for client-visible key
        for fn in ("api_key", "key", "token", "value", "client_key", "client_token", "secret", "access_key"):
            v = row.get(fn)
            if isinstance(v, str) and v == key:
                return True
        # also allow id match (explicitly required by audit note)
        rid = row.get("id")
        if isinstance(rid, str) and rid == key:
            return True
        return False

    credential = None
    credential_source = None
    for fn in ("credentials.json", "api_keys.json", "keys.json", "auth_keys.json", "auth.json", "accounts.json", "workspaces.json"):
        data = _load(fn)
        for row in _iter_rows(data):
            if _matches_key(row, api_key):
                credential = row
                credential_source = fn
                break
        if credential is not None:
            break

    # If we couldn't find an explicit credential row, still allow operation only if the store
    # has some active credential somewhere AND api_key matches by id/value; otherwise unauthorized.
    if credential is None:
        # record dynamics even on auth failures
        rl = _rate_limit_check(None)
        if rl:
            _log("error", {"error": rl["error"]})
            return rl
        e = _err("UNAUTHORIZED", "No valid credential found for provided api_key", api_key=api_key)
        _log("error", {"error": e["error"]})
        return e

    cred_id = credential.get("id") if isinstance(credential.get("id"), str) else None

    rl = _rate_limit_check(cred_id)
    if rl:
        _log("error", {"error": rl["error"]}, credential_id=cred_id)
        return rl

    # Derive effective scopes/entitlements if present; otherwise default to broad read-only.
    scopes = None
    for k in ("scopes", "scope", "permissions", "entitlements"):
        v = credential.get(k)
        if isinstance(v, list):
            scopes = [x for x in v if isinstance(x, str)]
            break
        if isinstance(v, str):
            scopes = [s for s in [p.strip() for p in v.replace(",", " ").split()] if s]
            break
    if scopes is None:
        scopes = ["read:public"]

    # Attempt to locate parent identity if present (account/workspace/user). Do not fail if missing.
    identity = {}
    for k in ("account_id", "workspace_id", "user_id", "owner_id", "parent_id"):
        if credential.get(k) is not None:
            identity[k] = credential.get(k)

    # Usage snapshot for this credential+endpoint from logs
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    now2 = datetime.datetime.utcnow()
    one_min = now2 - datetime.timedelta(seconds=60)
    one_day = now2 - datetime.timedelta(days=1)
    used_min = 0
    used_day = 0
    for r in logs[-50000:]:
        if not isinstance(r, dict):
            continue
        if r.get("endpoint") != endpoint:
            continue
        if cred_id is not None and r.get("credential_id") != cred_id:
            continue
        ts = _parse_dt(r.get("timestamp") or r.get("ts"))
        if not ts:
            continue
        if ts >= one_day:
            used_day += 1
            if ts >= one_min:
                used_min += 1

    resp = {
        "credential": {
            "id": cred_id,
            "source": credential_source,
        },
        "identity": identity,
        "scopes": scopes,
        "rate_limit": {
            "window_seconds": 60,
            "limit": 120,
            "used": used_min,
            "remaining": max(0, 120 - used_min),
        },
        "quota": {
            "window": "day",
            "limit": 20000,
            "used": used_day,
            "remaining": max(0, 20000 - used_day),
        },
    }
    _log("ok", {"credential_source": credential_source, "used_min": used_min, "used_day": used_day}, credential_id=cred_id)
    return resp
